         for (int i = 0; i < uvChannels; i++)
         {
             mesh->mTextureCoords[i] = new aiVector3D[mesh->mNumVertices];
             mesh->mNumUVComponents[i] = 2; // 2D UVs

             if (primMesh->UvLayersNames[i] != nullptr)
             {
                 mesh->mTextureCoordsNames[i] = new aiString(ManagedToStdString(primMesh->UvLayersNames[i]).c_str());
             }
         }

         // Allocate color channels and set names
         for (int i = 0; i < colorChannels; i++)
         {
             mesh->mColors[i] = new aiColor4D[mesh->mNumVertices];


         }

         // Fill vertex data
         for (unsigned int i = 0; i < mesh->mNumVertices; i++)
         {
             PrimordialVertex^ vert = primMesh->Vertices[i];

             mesh->mVertices[i] = ToAiVector3D(vert->Position);
             mesh->mNormals[i] = ToAiVector3D(vert->Normal);

             // UVs
             if (vert->UVs != nullptr)
             {
                 for (int ch = 0; ch < System::Math::Min(vert->UVs->Length, uvChannels); ch++)
                 {
