             mesh->mBitangents[i] = aiVector3D(
                 vert->Bitangent.X,
                 vert->Bitangent.Y,
                 vert->Bitangent.Z
             );
         }
     }

     // Indices (faces)
     if (primMesh->Indices != nullptr)
     {
         mesh->mNumFaces = primMesh->Indices->Length / 3;
         mesh->mFaces = new aiFace[mesh->mNumFaces];

         for (unsigned int i = 0; i < mesh->mNumFaces; i++)
         {
             aiFace& face = mesh->mFaces[i];
             face.mNumIndices = 3;
             face.mIndices = new unsigned int[3];
             face.mIndices[0] = primMesh->Indices[i * 3 + 0];
             face.mIndices[1] = primMesh->Indices[i * 3 + 1];
             face.mIndices[2] = primMesh->Indices[i * 3 + 2];
         }
     }

     // Bones
     if (primMesh->Bones != nullptr && primMesh->Bones->Length > 0)
     {
         mesh->mNumBones = primMesh->Bones->Length;
         mesh->mBones = new aiBone * [mesh->mNumBones];

         for (int i = 0; i < primMesh->Bones->Length; i++)
         {
             aiBone* bone = new aiBone();
             String^ boneName = (primMesh->Bones[i]);
             bone->mName = aiString(ManagedToStdString(boneName).c_str());

             // Collect weights for this bone using native std::vector
             std::vector<aiVertexWeight> weights;

             for (int v = 0; v < primMesh->Vertices->Length; v++)
             {
                 PrimordialVertex^ vert = primMesh->Vertices[v];
                 if (vert->VertexWeights != nullptr)
                 {
                     for (int w = 0; w < vert->VertexWeights->Length; w++)
