bool AssimpSceneExporter::ExportScene(PrimordialScene^ primScene, String^ filePath,String^ formatId)
{
     try
     {
         Assimp::Exporter exporter;

         aiScene* scene = new aiScene();

         // Convert meshes
         if (primScene->Meshes != nullptr)
         {
             scene->mNumMeshes = primScene->Meshes->Length;
             scene->mMeshes = new aiMesh * [scene->mNumMeshes];

             for (int i = 0; i < primScene->Meshes->Length; i++)
             {
                 scene->mMeshes[i] = ConvertMesh(primScene->Meshes[i]);
             }
         }

        // Create root node
         scene->mRootNode = new aiNode();
         scene->mRootNode->mName = aiString("RootNode");

         // Create a child node for each mesh
         if (scene->mNumMeshes > 0)
         {
             scene->mRootNode->mNumChildren = scene->mNumMeshes;
             scene->mRootNode->mChildren = new aiNode * [scene->mNumMeshes];

             for (unsigned int i = 0; i < scene->mNumMeshes; i++)
             {
                 aiNode* meshNode = new aiNode();
                 meshNode->mName = scene->mMeshes[i]->mName; 
                 meshNode->mParent = scene->mRootNode;

                 meshNode->mNumMeshes = 1;
                 meshNode->mMeshes = new unsigned int[1];
                 meshNode->mMeshes[0] = i;

                 scene->mRootNode->mChildren[i] = meshNode;
             }
         }

         // Add bone nodes as additional children if needed
         if (primScene->Bones != nullptr && primScene->Bones->Length > 0)
         {
             unsigned int totalChildren = scene->mNumMeshes + primScene->Bones->Length;
             aiNode** newChildren = new aiNode * [totalChildren];

             // Copy existing mesh nodes
             for (unsigned int i = 0; i < scene->mNumMeshes; i++)
             {
                 newChildren[i] = scene->mRootNode->mChildren[i];
             }

             // Add bone nodes
             for (int i = 0; i < primScene->Bones->Length; i++)
             {
                 newChildren[scene->mNumMeshes + i] = ConvertNode(primScene->Bones[i], scene->mRootNode);
             }

             delete[] scene->mRootNode->mChildren;
             scene->mRootNode->mChildren = newChildren;
             scene->mRootNode->mNumChildren = totalChildren;
         }

         // Create a default material
         scene->mNumMaterials = 1;
         scene->mMaterials = new aiMaterial * [1];
         scene->mMaterials[0] = new aiMaterial();

         // Export
         std::string fileStr = ManagedToStdString(filePath).c_str();
         std::string formatStr = ManagedToStdString(formatId).c_str();

         aiReturn result = exporter.Export(scene, formatStr, fileStr);

         // Cleanup
       //  delete scene;
         return result == AI_SUCCESS;
     }
     catch (System::Exception^ ex)
     {
         System::Console::WriteLine("Export failed: " + ex->Message);
         return false;
     }

	}
